// Standard-input fixtures are generated by unittest; no application data is read.
import { validateRegistry, validateProfile, validateCatalog, nameKey } from "../extension/studio/contracts.mjs";
let source = "";
for await (const chunk of process.stdin) source += chunk;
const fixtures = JSON.parse(source);
const results = fixtures.records.map(record => {
  try {
    if (record.kind === "registry") validateRegistry(record.value);
    else if (record.kind === "profile") validateProfile(record.value, record.candidateId);
    else validateCatalog(record.value, record.kind);
    return true;
  } catch { return false; }
});
process.stdout.write(JSON.stringify({ results, names: fixtures.names.map(nameKey) }));
